/**
 * Master Device cryptography for the Trust Center (step-up contract v1).
 *
 * The device key is an ECDSA P-256 key generated by WebCrypto with a NON-extractable private key:
 * the browser can use it to sign but never exports it, so approval requires this device's key, not
 * just a click. Signatures are raw r||s (IEEE P1363), which the API verifier accepts.
 *
 * Before signing, the page checks that the server-provided signing payload says exactly what the
 * page displays (challenge, subject, client, action, device, expiry). It never signs bytes that
 * differ from what the person approved on screen.
 *
 * Pure functions over WebCrypto: works in browsers and in Node (>= 20) for tests.
 */

export const STEP_UP_SIGNING_VERSION = "trustid-step-up/v1";
export const ENROLLMENT_SIGNING_VERSION = "trustid-master-device-enroll/v1";
export const REVOKE_SIGNING_VERSION = "trustid-master-device-revoke/v1";

const subtle = () => globalThis.crypto.subtle;

function toB64url(bytes: ArrayBuffer | Uint8Array): string {
  const view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let binary = "";
  for (const b of view) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export type DeviceKeyPair = { privateKey: CryptoKey; publicKeySpki: string };

/** New device key: private key non-extractable, public key exported as base64url SPKI. */
export async function generateDeviceKey(): Promise<DeviceKeyPair> {
  const pair = (await subtle().generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, ["sign", "verify"])) as CryptoKeyPair;
  if (pair.privateKey.extractable) throw new Error("Device private key must be non-extractable");
  const spki = await subtle().exportKey("spki", pair.publicKey);
  return { privateKey: pair.privateKey, publicKeySpki: toB64url(spki) };
}

/** Random device identifier (the server stores only its peppered hash). */
export function newDeviceFingerprint(): string {
  return toB64url(globalThis.crypto.getRandomValues(new Uint8Array(32)));
}

export async function signPayload(privateKey: CryptoKey, payload: string): Promise<string> {
  const signature = await subtle().sign({ name: "ECDSA", hash: "SHA-256" }, privateKey, new TextEncoder().encode(payload));
  return toB64url(signature);
}

/** "key=value" lines after the version line. */
export function parseSigningPayload(payload: string): { version: string; fields: Record<string, string> } {
  const [version = "", ...lines] = payload.split("\n");
  const fields: Record<string, string> = {};
  for (const line of lines) {
    const i = line.indexOf("=");
    if (i <= 0) throw new Error("Malformed signing payload");
    const key = line.slice(0, i);
    if (key in fields) throw new Error("Malformed signing payload");
    fields[key] = line.slice(i + 1);
  }
  return { version, fields };
}

export type DisplayedChallenge = {
  challenge_id: string;
  action: string;
  expires_at: string;
  method: string;
};

/**
 * Throws unless the step-up signing payload describes exactly the request shown to the person:
 * this challenge, this action, this device, this expiry, the expected subject, not yet expired.
 */
export function assertStepUpPayloadMatches(
  payload: string,
  shown: DisplayedChallenge,
  expected: { trustId: string; masterDeviceId: string },
  now = new Date(),
): void {
  const { version, fields } = parseSigningPayload(payload);
  const problems: string[] = [];
  if (version !== STEP_UP_SIGNING_VERSION) problems.push("version");
  if (shown.method !== "master_device") problems.push("method");
  if (fields.challenge !== shown.challenge_id) problems.push("challenge");
  if (fields.sub !== expected.trustId) problems.push("subject");
  if (fields.action !== shown.action) problems.push("action");
  if (fields.device !== expected.masterDeviceId) problems.push("device");
  if (!fields.client) problems.push("client");
  if (!fields.operation || !fields.session) problems.push("binding");
  if (fields.exp !== new Date(shown.expires_at).toISOString()) problems.push("expiry");
  if (Date.parse(fields.exp ?? "") <= now.getTime()) problems.push("expired");
  if (problems.length) throw new Error(`Signing payload does not match the displayed request (${problems.join(", ")})`);
}

/** Throws unless the enrollment payload binds this subject and this exact public key. */
export async function assertEnrollmentPayloadMatches(payload: string, expected: { trustId: string; publicKeySpki: string }) {
  const { version, fields } = parseSigningPayload(payload);
  const spki = Uint8Array.from(atob(expected.publicKeySpki.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));
  const thumbprint = toB64url(await subtle().digest("SHA-256", spki));
  if (version !== ENROLLMENT_SIGNING_VERSION || fields.sub !== expected.trustId || fields.key !== thumbprint || !fields.enrollment) {
    throw new Error("Enrollment payload does not match this device key");
  }
}

export function revokePayload(trustId: string, masterDeviceId: string) {
  return [REVOKE_SIGNING_VERSION, `sub=${trustId}`, `device=${masterDeviceId}`].join("\n");
}

/** SHA-256 thumbprint of a base64url SPKI, as the server reports key_thumbprint. */
export async function keyThumbprint(publicKeySpki: string): Promise<string> {
  const spki = Uint8Array.from(atob(publicKeySpki.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));
  return toB64url(await subtle().digest("SHA-256", spki));
}
